-- Open leave (all years) and active staff holding posted loans. Columns: k, n, v
SELECT 'open_leaves' K, COUNT(*) N, NVL(SUM(VACATION_NO_OF_DAY),0) V FROM {P}PS_STAFF_VACATIONS WHERE POST_FLAG='O' UNION ALL SELECT 'loans_open_active_staff', COUNT(DISTINCT l.STAFF_ID), ROUND(SUM(l.LOAN_AMOUNT)) FROM {P}PR_STAFF_LOANS l WHERE l.LOAN_STATUS='P' AND l.STAFF_ID IN (SELECT STAFF_ID FROM {P}PS_STAFF_CONTRACT WHERE STATUS='A' AND CURRENT_CONTRACT='Y') UNION ALL SELECT 'loans_on_leavers', COUNT(DISTINCT l.STAFF_ID), ROUND(SUM(l.LOAN_AMOUNT)) FROM {P}PR_STAFF_LOANS l WHERE l.LOAN_STATUS='P' AND l.STAFF_ID NOT IN (SELECT STAFF_ID FROM {P}PS_STAFF_CONTRACT WHERE STATUS='A' AND CURRENT_CONTRACT='Y')
